import{_ as t,o,c as n,a0 as r}from"./chunks/framework.Cp0xpwNH.js";const p=JSON.parse('{"title":"Research Guidelines for Dutch B1 Curriculum","description":"","frontmatter":{},"headers":[],"relativePath":"RESEARCH_GUIDELINES.md","filePath":"RESEARCH_GUIDELINES.md"}'),s={name:"RESEARCH_GUIDELINES.md"};function a(i,e,l,u,c,h){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="research-guidelines-for-dutch-b1-curriculum" tabindex="-1">Research Guidelines for Dutch B1 Curriculum <a class="header-anchor" href="#research-guidelines-for-dutch-b1-curriculum" aria-label="Permalink to &quot;Research Guidelines for Dutch B1 Curriculum&quot;">​</a></h1><p>When you conduct external research for lesson content, you will encounter clarifying questions from your research source. This document provides <strong>standing answers</strong> to the most common questions so you get consistent, high-quality output every time.</p><hr><h2 id="common-clarifying-questions-standing-answers" tabindex="-1">Common Clarifying Questions &amp; Standing Answers <a class="header-anchor" href="#common-clarifying-questions-standing-answers" aria-label="Permalink to &quot;Common Clarifying Questions &amp; Standing Answers&quot;">​</a></h2><h3 id="question-1-should-i-focus-on-netherlands-dutch-nl-or-include-belgian-dutch-flemish" tabindex="-1">Question 1: Should I focus on Netherlands Dutch (NL) or include Belgian Dutch (Flemish)? <a class="header-anchor" href="#question-1-should-i-focus-on-netherlands-dutch-nl-or-include-belgian-dutch-flemish" aria-label="Permalink to &quot;Question 1: Should I focus on Netherlands Dutch (NL) or include Belgian Dutch (Flemish)?&quot;">​</a></h3><p><strong>Answer:</strong> <strong>Focus strictly on Netherlands Dutch (Standard Dutch / Standaardnederlands).</strong></p><ul><li><strong>Why:</strong> The curriculum is designed for learners in/interacting with the Netherlands.</li><li><strong>Exception:</strong> Cultural notes may mention that Belgian Dutch exists (e.g., &quot;In Belgium, the word X is pronounced Y&quot;), but this is secondary.</li><li><strong>Spelling:</strong> Use Netherlands spelling standards (e.g., &quot;nummers&quot; not &quot;numers&quot;).</li><li><strong>Pronunciation:</strong> Netherlands accent/pronunciation only.</li></ul><p><strong>You can say:</strong> &quot;Netherlands Dutch only, please. This is for learners in/connecting with the Netherlands. Cultural notes can mention Belgian differences briefly, but focus on NL.&quot;</p><hr><h3 id="question-2-do-you-want-pronunciation-approximations-only-or-also-brief-teaching-tips-for-pronunciation" tabindex="-1">Question 2: Do you want pronunciation approximations only, or also brief teaching tips for pronunciation? <a class="header-anchor" href="#question-2-do-you-want-pronunciation-approximations-only-or-also-brief-teaching-tips-for-pronunciation" aria-label="Permalink to &quot;Question 2: Do you want pronunciation approximations only, or also brief teaching tips for pronunciation?&quot;">​</a></h3><p><strong>Answer:</strong> <strong>Both—approximations (English-style) AND brief teaching tips.</strong></p><p><strong>For Approximations:</strong></p><ul><li>Use English approximations only (no IPA symbols)</li><li>Mark stressed syllables with UPPERCASE</li><li>Examples: <code>MAAN-dag</code> (Monday), <code>FEB-roo-ah-ree</code> (February), <code>KRAAR-oo-ver</code> (quarter past)</li></ul><p><strong>For Teaching Tips:</strong></p><ul><li>Include 1-2 sentence guidance per sound if it differs significantly from English</li><li>Example: &quot;The Dutch &#39;ch&#39; is like Spanish &#39;jota&#39; (guttural), not English &#39;ch&#39; in &#39;church&#39;&quot;</li><li>Focus on sounds that are hard for English speakers</li></ul><p><strong>You can say:</strong> &quot;Please include English pronunciation approximations (with UPPERCASE stress marks) AND brief teaching tips (1-2 sentences) for Dutch sounds that differ from English. E.g., approximation: KRAAR-oo-ver, tip: The &#39;aa&#39; is like English &#39;ah&#39; but held slightly longer.&quot;</p><hr><h3 id="question-3-should-the-content-be-concise-for-lesson-integration-or-more-expanded-for-teacher-reference" tabindex="-1">Question 3: Should the content be concise for lesson integration or more expanded for teacher reference? <a class="header-anchor" href="#question-3-should-the-content-be-concise-for-lesson-integration-or-more-expanded-for-teacher-reference" aria-label="Permalink to &quot;Question 3: Should the content be concise for lesson integration or more expanded for teacher reference?&quot;">​</a></h3><p><strong>Answer:</strong> <strong>Concise for lesson integration, but complete and reference-ready.</strong></p><p><strong>Be concise on:</strong></p><ul><li>Grammar explanations (2-3 paragraphs per concept, not textbook chapters)</li><li>Dialogue length (2-3 exchanges per dialogue, not full conversations)</li><li>Exercise descriptions (enough detail to create a lesson, not elaborate scaffolding)</li></ul><p><strong>Be complete on:</strong></p><ul><li>All required sections (no skipping or abbreviating required fields)</li><li>Vocabulary table (every word needs all 8 columns)</li><li>Example sentences (full Dutch + English, not abbreviated)</li><li>Assessment criteria (clear, measurable standards)</li></ul><p><strong>You can say:</strong> &quot;Keep explanations concise but complete—2-3 paragraphs per grammar topic, 2-3 exchanges per dialogue. But include all required sections and fields. This is for direct lesson integration, not supplementary teacher guides.&quot;</p><hr><h3 id="question-4-anything-else-i-should-know-about-your-curriculum" tabindex="-1">Question 4: Anything else I should know about your curriculum? <a class="header-anchor" href="#question-4-anything-else-i-should-know-about-your-curriculum" aria-label="Permalink to &quot;Question 4: Anything else I should know about your curriculum?&quot;">​</a></h3><p><strong>Answer:</strong> Provide these key constraints:</p><ol><li><strong>One new grammar concept per lesson maximum</strong></li><li><strong>20-35 new vocabulary words per lesson</strong></li><li><strong>All examples must use ONLY previously taught + current-lesson vocabulary/grammar</strong> (no preview of future lessons)</li><li><strong>Days, months, seasons are case-sensitive</strong> (lowercase in running text, uppercase only in headings/formal lists in Dutch)</li><li><strong>Cultural notes should help English speakers understand Dutch context</strong> (punctuality, holidays, formatting conventions, etc.)</li><li><strong>All dialogue must sound natural and practical</strong> (reflecting real Dutch life: work, school, appointments, seasonal activities)</li><li><strong>For A0-06 specifically:</strong> Days/months/seasons are the primary focus; time prepositions (om, op, in) are secondary; frequency expressions (elke dag, elke week) are brief introduction</li></ol><p><strong>You can say:</strong> &quot;A few constraints: (1) One grammar concept per lesson max, (2) 20-35 new vocab words, (3) Examples use ONLY taught or current-lesson vocabulary—no future lessons, (4) Dutch capitalization rules matter for days/months (lowercase in running text), (5) Cultural notes should help English speakers understand Dutch context, (6) Keep dialogue natural and practical.&quot;</p><hr><h2 id="full-instruction-for-your-research-source" tabindex="-1">Full Instruction for Your Research Source <a class="header-anchor" href="#full-instruction-for-your-research-source" aria-label="Permalink to &quot;Full Instruction for Your Research Source&quot;">​</a></h2><p>When you&#39;re ready to request research, you can paste this into your conversation with your research source:</p><hr><p><strong>I need research output for A0-06 (Dutch B1 Curriculum lesson on Telling Time and Dates).</strong></p><p><strong>Please use these parameters:</strong></p><ol><li><strong>Dutch variant:</strong> Netherlands Dutch (Standard Dutch / Standaardnederlands) only</li><li><strong>Pronunciation:</strong> English approximations only (no IPA); mark stressed syllables in UPPERCASE; include 1-2 sentence teaching tips if the sound differs significantly from English</li><li><strong>Content scope:</strong> Concise but complete—2-3 paragraphs per grammar topic, all required fields filled, no abbreviated sections</li><li><strong>Key constraints:</strong><ul><li>One grammar concept per lesson max</li><li>20-35 new vocabulary words</li><li>Examples use ONLY previously taught (A0-01 through A0-05) + current-lesson (A0-06) vocabulary and grammar</li><li>Dutch capitalization matters (days/months lowercase in running text, uppercase in headings only)</li><li>Cultural notes explain Dutch context for English speakers (punctuality, holidays, formatting, etc.)</li><li>Dialogue must sound natural and practical (real Dutch life)</li><li>For A0-06: Days/months/seasons are primary; time prepositions (om, op, in) are secondary; frequency (elke dag, elke week) is brief intro</li></ul></li></ol><p><strong>Please follow the output format in <code>shared/prompts/A0-06-research-request.md</code>.</strong></p><hr><h2 id="when-you-get-back-the-research-output" tabindex="-1">When You Get Back the Research Output <a class="header-anchor" href="#when-you-get-back-the-research-output" aria-label="Permalink to &quot;When You Get Back the Research Output&quot;">​</a></h2><ol><li><strong>Check against this guide</strong> -- Do all 6 sections follow the standing answers?</li><li><strong>Paste the output here</strong> -- I&#39;ll validate it fully and run the integration workflow</li><li><strong>Validation</strong> -- I check: <ul><li>Grammar/vocab only from A0-01 to A0-06</li><li>Vocabulary table complete (all 8 columns)</li><li>Dialogues realistic and coherent</li><li>Exercise types are specific and actionable</li><li>Assessment criteria are measurable</li><li>Pronunciation approximations use UPPERCASE stress marks</li><li>No capitalization errors (days/months lowercase)</li></ul></li></ol><p>If validation passes → Full lesson creation, CURRICULUM.md update, CHANGELOG.md update, VitePress publish, next lesson request generated.</p><hr><h2 id="tl-dr-quick-reference" tabindex="-1">TL;DR Quick Reference <a class="header-anchor" href="#tl-dr-quick-reference" aria-label="Permalink to &quot;TL;DR Quick Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td><strong>Netherlands vs. Belgium?</strong></td><td>Netherlands Dutch only (NL standard). Brief mention of Flemish in cultural notes OK.</td></tr><tr><td><strong>Pronunciation: approximations or tips?</strong></td><td>Both. English-only approximations (UPPERCASE stress) + 1-2 teaching tips for hard sounds.</td></tr><tr><td><strong>Concise or expanded?</strong></td><td>Concise but complete. 2-3 paragraphs per topic, all required sections/fields filled.</td></tr><tr><td><strong>Anything else?</strong></td><td>One grammar concept per lesson max, 20-35 vocab, use ONLY taught + current vocab/grammar, Dutch capitalization matters, natural dialogue.</td></tr></tbody></table><hr><h2 id="example-answers-to-give-your-research-source" tabindex="-1">Example Answers to Give Your Research Source <a class="header-anchor" href="#example-answers-to-give-your-research-source" aria-label="Permalink to &quot;Example Answers to Give Your Research Source&quot;">​</a></h2><p><strong>You:</strong> &quot;I need research for Dutch A0-06 (telling time and dates). Can you help?&quot;</p><p><strong>Research source:</strong> &quot;I see you want a full A0-level lesson research package on telling time and dates in Dutch with grammar, vocabulary, dialogues, culture, exercises, and assessment. To make sure I cover what you need: (1) Should I focus on Netherlands Dutch or include Belgian Dutch? (2) Do you want pronunciation approximations only or teaching tips too? (3) Should it be concise or expanded?&quot;</p><p><strong>You:</strong> &quot;Netherlands Dutch only, please. Include English pronunciation approximations with UPPERCASE stress marks (like &#39;MAAN-dag&#39;) PLUS brief teaching tips (1-2 sentences) if the Dutch sound is hard for English speakers. Keep explanations concise—2-3 paragraphs per grammar topic—but make sure all required sections and fields are complete. Also, use ONLY vocabulary from lessons A0-01 through A0-06 in the examples, no future lessons.&quot;</p><p><strong>Research source:</strong> &quot;Got it. One more thing—anything else about your curriculum I should know?&quot;</p><p><strong>You:</strong> &quot;Yes: One new grammar concept per lesson max, 20-35 new vocab words, Dutch capitalization matters (days/months lowercase in running text, uppercase only in formal headings), cultural notes should help English speakers understand Dutch context, and all dialogue should sound natural and reflect real Dutch life (work, school, appointments, seasonal activities). For A0-06 specifically, days/months/seasons are the primary focus; time prepositions and frequency expressions are secondary.&quot;</p><p><strong>Research source:</strong> &quot;Perfect! Here&#39;s your research output...&quot;</p><hr><h2 id="keep-this-file-handy" tabindex="-1">Keep This File Handy <a class="header-anchor" href="#keep-this-file-handy" aria-label="Permalink to &quot;Keep This File Handy&quot;">​</a></h2><p>Bookmark or reference this file every time you conduct external research. It will:</p><ul><li>Save you time answering clarifying questions</li><li>Ensure consistent, high-quality research output</li><li>Make the integration process faster (because the output meets standards from the start)</li><li>Reduce back-and-forth corrections</li></ul><p><strong>File location:</strong> <code>docs/RESEARCH_GUIDELINES.md</code></p>',57)])])}const g=t(s,[["render",a]]);export{p as __pageData,g as default};
